create or replace function app.approve_finance_refund(p_refund_id uuid,p_approve boolean,p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$declare v public.finance_refunds%rowtype;v_note text:=nullif(btrim(coalesce(p_notes,'')),'');begin if not app.has_permission('finance_refunds.approve') then raise exception 'Tidak memiliki izin approval refund.' using errcode='42501';end if;select * into v from public.finance_refunds where id=p_refund_id for update;if not found then raise exception 'Refund tidak ditemukan.' using errcode='P0002';end if;if v.status<>'requested' then raise exception 'Hanya refund requested yang dapat direview.' using errcode='23514';end if;if v.requested_by=auth.uid() then raise exception 'Requester tidak dapat menyetujui atau menolak refund sendiri.' using errcode='42501';end if;if not p_approve and (v_note is null or length(v_note)<5) then raise exception 'Alasan penolakan refund wajib diisi minimal 5 karakter.' using errcode='22023';end if;update public.finance_refunds set status=case when p_approve then 'approved'::public.finance_refund_status else 'rejected'::public.finance_refund_status end,approved_by=auth.uid(),approved_at=now(),notes=coalesce(v_note,notes) where id=p_refund_id;insert into public.audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,summary,changes) values(auth.uid(),app.current_actor_type(),case when p_approve then 'finance.refund_approved' else 'finance.refund_rejected' end,'finance_refund',p_refund_id,case when p_approve then 'Refund disetujui.' else 'Refund ditolak.' end,jsonb_build_object('invoice_id',v.invoice_id,'payment_id',v.payment_id,'amount',v.amount,'decision_note',v_note));return p_refund_id;end$$;
create or replace function app.process_approved_finance_refund(p_refund_id uuid,p_proof_asset_id uuid,p_bank_reference text) returns uuid language plpgsql security definer set search_path='' as $$declare v public.finance_refunds%rowtype;v_asset public.media_assets%rowtype;v_ref text:=btrim(coalesce(p_bank_reference,''));begin if not app.has_permission('finance_refunds.process') then raise exception 'Tidak memiliki izin memproses refund.' using errcode='42501';end if;if length(v_ref)<3 then raise exception 'Referensi transaksi refund wajib diisi.' using errcode='22023';end if;select * into v from public.finance_refunds where id=p_refund_id for update;if not found then raise exception 'Refund tidak ditemukan.' using errcode='P0002';end if;if v.status<>'approved' then raise exception 'Hanya refund approved yang dapat diproses.' using errcode='23514';end if;if v.requested_by=auth.uid() or v.approved_by=auth.uid() then raise exception 'Requester/approver tidak dapat memproses refund yang sama.' using errcode='42501';end if;if exists(select 1 from public.finance_refunds r where r.status='processed' and lower(btrim(r.bank_reference))=lower(v_ref)) then raise exception 'Referensi transaksi refund sudah digunakan.' using errcode='23505';end if;select * into v_asset from public.media_assets where id=p_proof_asset_id and bucket='company-documents' and path like 'finance/refunds/%' and visibility='restricted' and finalized_at is not null and uploaded_by=auth.uid();if not found then raise exception 'Bukti refund tidak valid atau bukan milik pengguna aktif.' using errcode='23514';end if;if exists(select 1 from public.finance_refunds where proof_asset_id=p_proof_asset_id) then raise exception 'Bukti refund sudah digunakan.' using errcode='23505';end if;update public.finance_refunds set status='processed',processed_by=auth.uid(),processed_at=now(),proof_asset_id=p_proof_asset_id,bank_reference=v_ref where id=p_refund_id;return p_refund_id;end$$;